import unittest
import configparser
from settings import load_settings

class Settings(unittest.TestCase):
    def test_case_and_percent(self):
        result=load_settings('[DEFAULT]\nRegion=west\n[client]\nApiKey=Upper\napikey=lower\nLimit=95%\nTemplate=%(missing)s\n')
        self.assertEqual(result,{'client':{'Region':'west','ApiKey':'Upper','apikey':'lower','Limit':'95%','Template':'%(missing)s'}})
        self.assertEqual(load_settings(''),{})
        self.assertEqual(load_settings('[empty]\n'),{'empty':{}})
    def test_invalid(self):
        for text in ['Key=value','[a]\nKey=1\nKey=2\n']:
            with self.assertRaises(configparser.Error): load_settings(text)

if __name__ == '__main__':
    unittest.main()

